FIG_22_1_HTML = '<figure class="diagram-container diagram-figure" id="fig-22-1">\n<div class="diagram-scroll">\n<svg aria-labelledby="fig22-1-title fig22-1-desc" height="520" role="img" viewbox="0 0 960 520" width="960" xmlns="http://www.w3.org/2000/svg">\n<title id="fig22-1-title">Google Cloud Hierarchical IAM Policy Inheritance and Additive Union Flow</title>\n<desc id="fig22-1-desc">Architectural diagram illustrating how IAM allow policies flow downward through the Google Cloud resource hierarchy and form a mathematical union at the leaf resource, demonstrating that project-level bindings cannot subtract folder-level permissions.</desc>\n<defs>\n<lineargradient id="p22-f1-bg" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#0c101d"></stop>\n<stop offset="100%" stop-color="#121526"></stop>\n</lineargradient>\n<lineargradient id="p22-f1-node-org" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#1e293b"></stop>\n<stop offset="100%" stop-color="#0f172a"></stop>\n</lineargradient>\n<lineargradient id="p22-f1-node-folder" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#1e293b"></stop>\n<stop offset="100%" stop-color="#1e1b4b"></stop>\n</lineargradient>\n<lineargradient id="p22-f1-node-proj" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#1e293b"></stop>\n<stop offset="100%" stop-color="#172554"></stop>\n</lineargradient>\n<lineargradient id="p22-f1-union" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#1c1917"></stop>\n<stop offset="100%" stop-color="#292524"></stop>\n</lineargradient>\n<marker id="p22-f1-arrow" markerheight="6" markerwidth="6" orient="auto-start-reverse" refx="8" refy="5" viewbox="0 0 10 10">\n<path d="M 0 1 L 9 5 L 0 9 z" fill="#38bdf8"></path>\n</marker>\n<marker id="p22-f1-arrow-warn" markerheight="6" markerwidth="6" orient="auto-start-reverse" refx="8" refy="5" viewbox="0 0 10 10">\n<path d="M 0 1 L 9 5 L 0 9 z" fill="#f43f5e"></path>\n</marker>\n</defs>\n<!-- Background Canvas -->\n<rect fill="url(#p22-f1-bg)" height="520" rx="12" stroke="#1e293b" stroke-width="1.5" width="960"></rect>\n<!-- Header Label -->\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="16" font-weight="700" x="32" y="36">HIERARCHICAL IAM EVALUATION ENGINE: ADDITIVE POLICY UNION</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="12" x="32" y="56">Policies flow downward; effective permissions equal the mathematical union of all ancestor allow bindings.</text>\n<!-- Top Container: Organization Node -->\n<g transform="translate(40, 80)">\n<rect fill="url(#p22-f1-node-org)" height="85" rx="8" stroke="#38bdf8" stroke-width="1.5" width="400"></rect>\n<rect fill="#38bdf8" height="85" rx="4" width="8" x="0" y="0"></rect>\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="24" y="24">ORGANIZATION APEX: organizations/714029482103</text>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="600" x="24" y="42">Domain: brightloaf.com</text>\n<text fill="#cbd5e1" font-family="ui-monospace, monospace" font-size="11" x="24" y="60">Principal: sec-team@brightloaf.com → roles/securityReviewer</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="24" y="74">Permissions: {resourcemanager.organizations.get, iam.roles.list}</text>\n</g>\n<!-- Hierarchy Arrow Org -> Folder -->\n<line marker-end="url(#p22-f1-arrow)" stroke="#38bdf8" stroke-width="2" x1="240" x2="240" y1="165" y2="195"></line>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="250" y="185">Inherits Downward</text>\n<!-- Middle Container: Folder Tier -->\n<g transform="translate(40, 200)">\n<rect fill="url(#p22-f1-node-folder)" height="95" rx="8" stroke="#f43f5e" stroke-width="1.5" width="400"></rect>\n<rect fill="#f43f5e" height="95" rx="4" width="8" x="0" y="0"></rect>\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="24" y="24">INTERMEDIATE FOLDER: folders/839102482019</text>\n<text fill="#f43f5e" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="600" x="24" y="42">Display Name: Production-Fulfillment</text>\n<text fill="#fca5a5" font-family="ui-monospace, monospace" font-size="11" font-weight="600" x="24" y="60">CRITICAL: contractor-group@ → roles/editor</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="24" y="74">Injected: {spanner.databases.drop, compute.instances.create, ...}</text>\n<text fill="#f43f5e" font-family="system-ui, -apple-system, sans-serif" font-size="9" font-style="italic" x="24" y="88">Cannot be attenuated by lower nodes</text>\n</g>\n<!-- Hierarchy Arrow Folder -> Project -->\n<line marker-end="url(#p22-f1-arrow)" stroke="#38bdf8" stroke-width="2" x1="240" x2="240" y1="295" y2="325"></line>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="250" y="315">Inherits Downward</text>\n<!-- Bottom Container: Project Tier -->\n<g transform="translate(40, 330)">\n<rect fill="url(#p22-f1-node-proj)" height="90" rx="8" stroke="#f59e0b" stroke-width="1.5" width="400"></rect>\n<rect fill="#f59e0b" height="90" rx="4" width="8" x="0" y="0"></rect>\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="24" y="24">PROJECT LEAF: bl-order-fulfill-prod</text>\n<text fill="#f59e0b" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="600" x="24" y="42">Project Number: 109283746152</text>\n<text fill="#fde68a" font-family="ui-monospace, monospace" font-size="11" x="24" y="60">Local Binding Attempt: contractor-group@ → roles/viewer</text>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="24" y="76">FALLACY: Binding "viewer" does NOT revoke parent "editor"!</text>\n</g>\n<!-- Hierarchy Arrow Project -> Leaf Resource -->\n<line marker-end="url(#p22-f1-arrow)" stroke="#38bdf8" stroke-width="2" x1="240" x2="240" y1="420" y2="445"></line>\n<!-- Leaf Target Resource -->\n<g transform="translate(40, 448)">\n<rect fill="#1e293b" height="52" rx="6" stroke="#38bdf8" stroke-width="1" width="400"></rect>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="24" y="22">TARGET RESOURCE: Cloud Spanner Database</text>\n<text fill="#94a3b8" font-family="ui-monospace, monospace" font-size="10" x="24" y="38">projects/bl-order-fulfill-prod/instances/bl-spanner/databases/orders-db</text>\n</g>\n<!-- Right Panel: Mathematical Union Engine -->\n<g transform="translate(480, 80)">\n<rect fill="url(#p22-f1-union)" height="420" rx="10" stroke="#334155" stroke-width="1.5" width="440"></rect>\n<rect fill="#1e293b" height="38" rx="10" width="440" x="0" y="0"></rect>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="20" y="24">EVALUATION LOGIC: MATHEMATICAL SET UNION</text>\n<!-- Formula Box -->\n<g transform="translate(20, 52)">\n<rect fill="#0f172a" height="56" rx="6" stroke="#38bdf8" stroke-width="1" width="400"></rect>\n<text fill="#e2e8f0" font-family="ui-monospace, monospace" font-size="11" x="14" y="22">P_effective(R) = P(Org) ∪ P(Folder) ∪ P(Project) ∪ P(Resource)</text>\n<text fill="#22c55e" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="14" y="42">✓ Principle: Permissions are purely additive across all ancestors.</text>\n</g>\n<!-- Evaluation Walkthrough -->\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="20" y="132">Evaluation for contractor-group@brightloaf.com:</text>\n<rect fill="#111827" height="60" rx="6" stroke="#1e293b" stroke-width="1" width="400" x="20" y="142"></rect>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="30" y="162">1. Query Org Policy:</text>\n<text fill="#cbd5e1" font-family="ui-monospace, monospace" font-size="10" x="170" y="162">No direct grant → ∅</text>\n<text fill="#f43f5e" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="30" y="180">2. Query Folder Policy:</text>\n<text fill="#fca5a5" font-family="ui-monospace, monospace" font-size="10" x="170" y="180">roles/editor → {spanner.databases.drop, ...}</text>\n<text fill="#f59e0b" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="30" y="196">3. Query Project Policy:</text>\n<text fill="#cbd5e1" font-family="ui-monospace, monospace" font-size="10" x="170" y="196">roles/viewer → {spanner.databases.get, ...}</text>\n<!-- Calculation Result -->\n<g transform="translate(20, 215)">\n<rect fill="#3f1219" height="90" rx="6" stroke="#f43f5e" stroke-width="1.5" width="400"></rect>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="14" y="24">RESULT: PRIVILEGE ESCALATION VIA INHERITANCE</text>\n<text fill="#fecaca" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="14" y="44">Action attempted: spanner.databases.drop</text>\n<text fill="#fecaca" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="14" y="62">Check: spanner.databases.drop ∈ ({editor} ∪ {viewer}) = TRUE</text>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="14" y="80">DECISION: ALLOWED → Table dropped unintentionally!</text>\n</g>\n<!-- Correct Architectural Remedy -->\n<g transform="translate(20, 318)">\n<rect fill="#052e16" height="86" rx="6" stroke="#22c55e" stroke-width="1.2" width="400"></rect>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="14" y="22">ARCHITECTURAL REMEDIES:</text>\n<text fill="#bbf7d0" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="14" y="40">1. Restrict broad roles to leaf non-production projects only.</text>\n<text fill="#bbf7d0" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="14" y="56">2. Use environment-first folder separation (/Prod vs /NonProd).</text>\n<text fill="#bbf7d0" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="14" y="72">3. Apply IAM Deny policies to block deletion at the project boundary.</text>\n</g>\n</g>\n</svg>\n</div>\n<figcaption>\n<strong>Figure 22.1: Google Cloud Hierarchical IAM Policy Inheritance and Additive Union Flow.</strong>\n    Demonstrates the downward propagation of IAM allow bindings across Organization, Folder, and Project tiers. Because IAM permissions are evaluated as the mathematical union of all ancestor policies, granting broad roles at a parent folder exposes leaf project resources to unintended administrative actions that cannot be revoked at the project level.\n  </figcaption>\n</figure>'

FIG_22_2_HTML = '<figure class="diagram-container diagram-figure" id="fig-22-2">\n<div class="diagram-scroll">\n<svg aria-labelledby="fig22-2-title fig22-2-desc" height="540" role="img" viewbox="0 0 960 540" width="960" xmlns="http://www.w3.org/2000/svg">\n<title id="fig22-2-title">Three-Plane Architectural Taxonomy: Labels vs. Resource Manager Tags vs. Network Tags</title>\n<desc id="fig22-2-desc">A three-column comparative architectural diagram differentiating Resource Labels for billing, Resource Manager Tags for IAM governance, and Network Tags for VPC firewall packet filtering.</desc>\n<defs>\n<lineargradient id="p22-f2-bg" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#0c101d"></stop>\n<stop offset="100%" stop-color="#121526"></stop>\n</lineargradient>\n<lineargradient id="p22-f2-col1" x1="0%" x2="0%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#0e2a38"></stop>\n<stop offset="100%" stop-color="#0b1726"></stop>\n</lineargradient>\n<lineargradient id="p22-f2-col2" x1="0%" x2="0%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#3b111e"></stop>\n<stop offset="100%" stop-color="#180b18"></stop>\n</lineargradient>\n<lineargradient id="p22-f2-col3" x1="0%" x2="0%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#382609"></stop>\n<stop offset="100%" stop-color="#1a1205"></stop>\n</lineargradient>\n</defs>\n<!-- Canvas Background -->\n<rect fill="url(#p22-f2-bg)" height="540" rx="12" stroke="#1e293b" stroke-width="1.5" width="960"></rect>\n<!-- Header -->\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="16" font-weight="700" x="32" y="34">ARCHITECTURAL TAXONOMY: THREE METADATA &amp; FILTERING PLANES</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="12" x="32" y="54">Comparing Resource Labels, Resource Manager Tags, and Network Tags across purpose, scope, and security boundaries.</text>\n<!-- COLUMN 1: Resource Labels -->\n<g transform="translate(32, 75)">\n<rect fill="url(#p22-f2-col1)" height="380" rx="10" stroke="#38bdf8" stroke-width="1.5" width="280"></rect>\n<rect fill="#0369a1" height="42" rx="10" width="280" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="14" y="26">1 · RESOURCE LABELS</text>\n<text fill="#7dd3fc" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="600" x="14" y="60">Plane: Operations &amp; Billing</text>\n<!-- Key Specs -->\n<g transform="translate(12, 72)">\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="16">TARGET / ATTACHMENT:</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="32">VMs, Buckets, SQL, Disks, Datasets</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="60">INHERITANCE:</text>\n<text fill="#f43f5e" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="0" y="76">NONE (Per-resource attribute)</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="104">SYNTAX &amp; LIMITS:</text>\n<text fill="#cbd5e1" font-family="ui-monospace, monospace" font-size="10" x="0" y="120">key:value (max 63 chars, regex)</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="0" y="134">Max 64 labels per resource</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="162">PRIMARY USES:</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="178">• BigQuery Cloud Billing breakdown</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="194">• Cost attribution / chargebacks</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="210">• Inventory filtering via gcloud/API</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="238">SECURITY / ACCESS CONTROL:</text>\n<text fill="#f87171" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="0" y="254">✗ NO IAM condition support</text>\n<text fill="#f87171" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="0" y="268">✗ ZERO effect on VPC firewalls</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="0" y="284">Mutated via resource update API</text>\n</g>\n</g>\n<!-- COLUMN 2: Resource Manager Tags -->\n<g transform="translate(340, 75)">\n<rect fill="url(#p22-f2-col2)" height="380" rx="10" stroke="#f43f5e" stroke-width="1.5" width="280"></rect>\n<rect fill="#be123c" height="42" rx="10" width="280" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="14" y="26">2 · RESOURCE MANAGER TAGS</text>\n<text fill="#fda4af" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="600" x="14" y="60">Plane: Central Governance &amp; IAM</text>\n<!-- Key Specs -->\n<g transform="translate(12, 72)">\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="16">TARGET / ATTACHMENT:</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="32">Orgs, Folders, Projects, Cloud Res</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="60">INHERITANCE:</text>\n<text fill="#22c55e" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="0" y="76">✓ YES (Inherited down tree)</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="104">SYNTAX &amp; LIMITS:</text>\n<text fill="#cbd5e1" font-family="ui-monospace, monospace" font-size="10" x="0" y="120">tagKeys/123 → tagValues/456</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="0" y="134">Max 50 tags bound per resource</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="162">PRIMARY USES:</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="178">• Conditional IAM: resource.matchTag()</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="194">• Organization Policy constraints</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="210">• Secure Tags for Next-Gen Firewalls</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="238">SECURITY / ACCESS CONTROL:</text>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="0" y="254">✓ Protected by TagAdmin/TagUser</text>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="0" y="268">✓ Tamper-resistant against devs</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="0" y="284">First-class Google Cloud resource</text>\n</g>\n</g>\n<!-- COLUMN 3: Network Tags -->\n<g transform="translate(648, 75)">\n<rect fill="url(#p22-f2-col3)" height="380" rx="10" stroke="#f59e0b" stroke-width="1.5" width="280"></rect>\n<rect fill="#b45309" height="42" rx="10" width="280" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="13" font-weight="700" x="14" y="26">3 · NETWORK TAGS</text>\n<text fill="#fcd34d" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="600" x="14" y="60">Plane: VPC Virtual Data Plane</text>\n<!-- Key Specs -->\n<g transform="translate(12, 72)">\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="16">TARGET / ATTACHMENT:</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="32">Compute Engine VMs &amp; Templates ONLY</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="60">INHERITANCE:</text>\n<text fill="#f43f5e" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="0" y="76">NONE (Per-VM instance attribute)</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="104">SYNTAX &amp; LIMITS:</text>\n<text fill="#cbd5e1" font-family="ui-monospace, monospace" font-size="10" x="0" y="120">string (lowercase, dashes, max 63)</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="0" y="134">Max 64 tags per VM instance</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="162">PRIMARY USES:</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="178">• VPC Firewall targetTags / sourceTags</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="194">• VPC Custom Route next-hop targets</text>\n<text fill="#e2e8f0" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="0" y="210">• Virtual distributed packet filtering</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="700" x="0" y="238">SECURITY / ACCESS CONTROL:</text>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="0" y="254">✗ Mutable via compute.instances.setTags</text>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="0" y="268">✗ Any VM editor can bypass firewall</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="0" y="284">Not a hardened security perimeter</text>\n</g>\n</g>\n<!-- Bottom Alert Callout -->\n<g transform="translate(32, 470)">\n<rect fill="#450a0a" height="52" rx="8" stroke="#f43f5e" stroke-width="1.2" width="896"></rect>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="18" y="22">ARCHITECTURAL PITFALL WARNING:</text>\n<text fill="#fecaca" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="18" y="38">Resource Labels have ZERO impact on VPC firewall rules or IAM policies. Applying \'role: order-db\' as a label does NOT filter network traffic; firewalls require Network Tags or Secure Tags!</text>\n</g>\n</svg>\n</div>\n<figcaption>\n<strong>Figure 22.2: Three-Plane Architectural Taxonomy: Labels vs. Resource Manager Tags vs. Network Tags.</strong>\n    Systematically compares the three metadata mechanisms in Google Cloud across attachment scope, inheritance mechanics, syntax, primary use cases, and security boundaries. Labels manage operational billing; Resource Manager Tags enforce centralized hierarchical governance; Network Tags execute distributed VPC packet filtering.\n  </figcaption>\n</figure>'

FIG_22_3_HTML = '<figure class="diagram-container diagram-figure" id="fig-22-3">\n<div class="diagram-scroll">\n<svg aria-labelledby="fig22-3-title fig22-3-desc" height="520" role="img" viewbox="0 0 960 520" width="960" xmlns="http://www.w3.org/2000/svg">\n<title id="fig22-3-title">Incident 22.1 Flow: Additive IAM Inheritance Escalation vs. Bounded Least-Privilege Architecture</title>\n<desc id="fig22-3-desc">Incident diagram contrasting the failed path where inherited folder-level editor permissions dropped a production database with the corrected path implementing environment folder segregation, leaf custom roles, IAM Deny guardrails, and idempotent event replay.</desc>\n<defs>\n<lineargradient id="p22-f3-bg" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#0c101d"></stop>\n<stop offset="100%" stop-color="#121526"></stop>\n</lineargradient>\n<marker id="p22-f3-fail-arrow" markerheight="6" markerwidth="6" orient="auto-start-reverse" refx="8" refy="5" viewbox="0 0 10 10">\n<path d="M 0 1 L 9 5 L 0 9 z" fill="#f43f5e"></path>\n</marker>\n<marker id="p22-f3-ok-arrow" markerheight="6" markerwidth="6" orient="auto-start-reverse" refx="8" refy="5" viewbox="0 0 10 10">\n<path d="M 0 1 L 9 5 L 0 9 z" fill="#22c55e"></path>\n</marker>\n</defs>\n<!-- Background -->\n<rect fill="url(#p22-f3-bg)" height="520" rx="12" stroke="#1e293b" stroke-width="1.5" width="960"></rect>\n<!-- Header Banner -->\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="16" font-weight="700" x="32" y="34">INCIDENT 22.1: ADDITIVE IAM INHERITANCE ESCALATION &amp; DEFENSE</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="12" x="32" y="54">Illustrating how inherited folder editor permissions overrode a project viewer role to drop production Spanner, and the corrected architecture.</text>\n<!-- TOP: Actor / Caller Identity -->\n<g transform="translate(40, 75)">\n<rect fill="#1e293b" height="58" rx="8" stroke="#334155" stroke-width="1.2" width="880"></rect>\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="20" y="24">CALLER IDENTITY: analytics-deployer@brightloaf-franchise-analytics.iam.gserviceaccount.com</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="20" y="44">Automated pipeline running schema updates; intended for staging but configured with production project credentials.</text>\n</g>\n<!-- LEFT SIDE: FAILED PATH -->\n<g transform="translate(40, 150)">\n<rect fill="#2d1219" height="280" rx="8" stroke="#f43f5e" stroke-width="1.5" width="420"></rect>\n<rect fill="#881337" height="34" rx="8" width="420" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="16" y="22">FAILED PATH: ADDITIVE INHERITANCE OVERRIDE</text>\n<!-- Step 1 -->\n<g transform="translate(16, 46)">\n<rect fill="#1f1118" height="48" rx="6" stroke="#f43f5e" stroke-width="1" width="388"></rect>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">1. Folder Binding: roles/editor</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="36">Parent folder grant injects spanner.databases.drop</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f3-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2" x1="210" x2="210" y1="94" y2="108"></line>\n<!-- Step 2 -->\n<g transform="translate(16, 112)">\n<rect fill="#1f1118" height="48" rx="6" stroke="#f43f5e" stroke-width="1" width="388"></rect>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">2. Project Binding: roles/viewer (Subtractive Fallacy)</text>\n<text fill="#fecaca" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="36">Viewer binding CANNOT subtract inherited editor role!</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f3-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2" x1="210" x2="210" y1="160" y2="174"></line>\n<!-- Step 3 Failure -->\n<g transform="translate(16, 178)">\n<rect fill="#450a0a" height="88" rx="6" stroke="#f43f5e" stroke-width="1.5" width="388"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="22">[FAILED PATH: DROP DATABASE AUTHORIZED]</text>\n<text fill="#fca5a5" font-family="ui-monospace, monospace" font-size="10" x="12" y="40">API: spanner.databases.drop → HTTP 200 OK</text>\n<text fill="#fecaca" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="58">✗ orders-db deleted; worker pods throw 404 Not Found</text>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="12" y="74">Result: 450 franchise stores cannot fetch order queue</text>\n</g>\n</g>\n<!-- RIGHT SIDE: CORRECTED PATH -->\n<g transform="translate(500, 150)">\n<rect fill="#0c2317" height="280" rx="8" stroke="#22c55e" stroke-width="1.5" width="420"></rect>\n<rect fill="#14532d" height="34" rx="8" width="420" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="16" y="22">CORRECTED PATH: LEAST-PRIVILEGE &amp; IAM DENY</text>\n<!-- Step 1 -->\n<g transform="translate(16, 46)">\n<rect fill="#061c12" height="48" rx="6" stroke="#22c55e" stroke-width="1" width="388"></rect>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">1. Environment-Segregated Folders (/Prod vs /NonProd)</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="36">No broad editor roles assigned at parent folder levels</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f3-ok-arrow)" stroke="#22c55e" stroke-width="2" x1="210" x2="210" y1="94" y2="108"></line>\n<!-- Step 2 -->\n<g transform="translate(16, 112)">\n<rect fill="#061c12" height="48" rx="6" stroke="#22c55e" stroke-width="1" width="388"></rect>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">2. Leaf Custom Role &amp; Org IAM Deny Policy</text>\n<text fill="#bbf7d0" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="36">Deny spanner.databases.drop on all automated service accounts</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f3-ok-arrow)" stroke="#22c55e" stroke-width="2" x1="210" x2="210" y1="160" y2="174"></line>\n<!-- Step 3 Corrected -->\n<g transform="translate(16, 178)">\n<rect fill="#052e16" height="88" rx="6" stroke="#22c55e" stroke-width="1.5" width="388"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="22">[CORRECTED PATH: PERMISSION DENIED &amp; PITR RECOVERY]</text>\n<text fill="#86efac" font-family="ui-monospace, monospace" font-size="10" x="12" y="40">API: spanner.databases.drop → HTTP 403 Forbidden</text>\n<text fill="#bbf7d0" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="58">✓ Spanner PITR restores db; Pub/Sub events replayed</text>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="12" y="74">Invariant Preserved: ≤ 1 physical fulfillment per unique order ID</text>\n</g>\n</g>\n<!-- Bottom Invariant Defense Summary -->\n<g transform="translate(40, 445)">\n<rect fill="#111827" height="58" rx="8" stroke="#334155" stroke-width="1.2" width="880"></rect>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="20" y="22">FULFILLMENT INVARIANT VERIFICATION BOUNDARY:</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="20" y="42">Cloud Spanner PITR restored schema and transactions up to 06:13 UTC. Replaying unacknowledged Pub/Sub queue events verified idempotent deduplication hashes, ensuring zero duplicate bread orders were produced across all 450 bakeries.</text>\n</g>\n</svg>\n</div>\n<figcaption>\n<strong>Figure 22.3: Incident Flow · Additive IAM Inheritance Escalation vs. Bounded Least-Privilege &amp; Deny Guardrails.</strong>\n    Contrasts the failure path where an inherited folder-level <code>roles/editor</code> grant permitted an unauthorized database drop against the corrected architecture enforcing environment folder segregation, leaf custom roles, and IAM Deny policies.\n    <br/><strong>Supplied facts:</strong> A contractor analytics service account issued a <code>DropDatabase</code> API call that succeeded despite an explicit project-level <code>roles/viewer</code> binding.\n    <br/><strong>Architectural inference:</strong> IAM allow policies are strictly additive; a project-level viewer binding cannot restrict permissions inherited from an ancestor folder editor binding.\n    <br/><strong>Expected post-fix behavior:</strong> Broad editor roles are purged from parent folders, IAM Deny policies prevent database deletion, and Spanner PITR restoration combined with idempotent event replays ensures ≤ 1 physical fulfillment per unique order ID.\n  </figcaption>\n</figure>'

FIG_22_4_HTML = '<figure class="diagram-container diagram-figure" id="fig-22-4">\n<div class="diagram-scroll">\n<svg aria-labelledby="fig22-4-title fig22-4-desc" height="520" role="img" viewbox="0 0 960 520" width="960" xmlns="http://www.w3.org/2000/svg">\n<title id="fig22-4-title">Incident 22.2 Flow: Resource Label vs. Network Tag Conflation in VPC Firewall Packet Filtering</title>\n<desc id="fig22-4-desc">Incident diagram showing how confusing Resource Labels with Compute Engine Network Tags left a production database instance without tag-based firewall filtering, falling through to a permissive fallback rule, and how adding explicit network tags and secure tags restored network isolation.</desc>\n<defs>\n<lineargradient id="p22-f4-bg" x1="0%" x2="100%" y1="0%" y2="100%">\n<stop offset="0%" stop-color="#0c101d"></stop>\n<stop offset="100%" stop-color="#121526"></stop>\n</lineargradient>\n<marker id="p22-f4-fail-arrow" markerheight="6" markerwidth="6" orient="auto-start-reverse" refx="8" refy="5" viewbox="0 0 10 10">\n<path d="M 0 1 L 9 5 L 0 9 z" fill="#f43f5e"></path>\n</marker>\n<marker id="p22-f4-ok-arrow" markerheight="6" markerwidth="6" orient="auto-start-reverse" refx="8" refy="5" viewbox="0 0 10 10">\n<path d="M 0 1 L 9 5 L 0 9 z" fill="#22c55e"></path>\n</marker>\n</defs>\n<!-- Background -->\n<rect fill="url(#p22-f4-bg)" height="520" rx="12" stroke="#1e293b" stroke-width="1.5" width="960"></rect>\n<!-- Header -->\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="16" font-weight="700" x="32" y="34">INCIDENT 22.2: METADATA CONFLATION &amp; VPC PACKET FILTERING DEFECT</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="12" x="32" y="54">VPC Firewalls evaluate Network Tags, not Resource Labels. Untagged instances fall through to default fallback rules.</text>\n<!-- Top Container: Staging Traffic Source -->\n<g transform="translate(40, 75)">\n<rect fill="#1e293b" height="55" rx="8" stroke="#334155" stroke-width="1.2" width="880"></rect>\n<text fill="#f8fafc" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="20" y="22">INCOMING PACKET: Staging Bastion (10.240.10.15) → Target: bl-order-db-prod-vm (10.128.0.45:5432)</text>\n<text fill="#94a3b8" font-family="system-ui, -apple-system, sans-serif" font-size="11" x="20" y="42">Security goal: Drop all non-production traffic to port 5432; permit only bl-order-api instances.</text>\n</g>\n<!-- LEFT SIDE: FAILED PATH -->\n<g transform="translate(40, 145)">\n<rect fill="#2d1219" height="285" rx="8" stroke="#f43f5e" stroke-width="1.5" width="420"></rect>\n<rect fill="#881337" height="34" rx="8" width="420" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="16" y="22">FAILED PATH: LABEL ASSIGNMENT ONLY</text>\n<!-- Box 1: Configuration Defect -->\n<g transform="translate(16, 46)">\n<rect fill="#1f1118" height="52" rx="6" stroke="#f43f5e" stroke-width="1" width="388"></rect>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">1. Terraform Configures Resource Labels Only</text>\n<text fill="#fecaca" font-family="ui-monospace, monospace" font-size="10" x="12" y="38">labels = { tier = "order-db" } ; tags = [] (EMPTY)</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f4-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2" x1="210" x2="210" y1="98" y2="112"></line>\n<!-- Box 2: Firewall Evaluation Miss -->\n<g transform="translate(16, 115)">\n<rect fill="#1f1118" height="52" rx="6" stroke="#f43f5e" stroke-width="1" width="388"></rect>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">2. VPC Firewall Checks targetTags: ["order-db"]</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="38">Tags do not match! Firewall ignores resource labels entirely.</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f4-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2" x1="210" x2="210" y1="167" y2="181"></line>\n<!-- Box 3: Exposure Fallthrough -->\n<g transform="translate(16, 184)">\n<rect fill="#450a0a" height="88" rx="6" stroke="#f43f5e" stroke-width="1.5" width="388"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="22">[FAILED PATH: FALLTHROUGH TO PERMISSIVE RULE]</text>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="40">✗ Packet matches allow-default-internal (10.128.0.0/9)</text>\n<text fill="#fecaca" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="58">✗ TCP handshake succeeds from staging bastion to port 5432</text>\n<text fill="#fca5a5" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="12" y="74">Result: Production database exposed to non-prod network</text>\n</g>\n</g>\n<!-- RIGHT SIDE: CORRECTED PATH -->\n<g transform="translate(500, 145)">\n<rect fill="#0c2317" height="285" rx="8" stroke="#22c55e" stroke-width="1.5" width="420"></rect>\n<rect fill="#14532d" height="34" rx="8" width="420" x="0" y="0"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="12" font-weight="700" x="16" y="22">CORRECTED PATH: NETWORK TAGS &amp; SECURE TAGS</text>\n<!-- Box 1: Correct Configuration -->\n<g transform="translate(16, 46)">\n<rect fill="#061c12" height="52" rx="6" stroke="#22c55e" stroke-width="1" width="388"></rect>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">1. Explicit Network Tag &amp; Secure Tag Applied</text>\n<text fill="#bbf7d0" font-family="ui-monospace, monospace" font-size="10" x="12" y="38">tags = ["order-db"] + TagBinding (env: prod)</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f4-ok-arrow)" stroke="#22c55e" stroke-width="2" x1="210" x2="210" y1="98" y2="112"></line>\n<!-- Box 2: Target Match -->\n<g transform="translate(16, 115)">\n<rect fill="#061c12" height="52" rx="6" stroke="#22c55e" stroke-width="1" width="388"></rect>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="20">2. Firewall Matches targetTags: ["order-db"]</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="38">Enforces sourceTags: ["order-api-tier"]. Staging tag is absent!</text>\n</g>\n<!-- Downward arrow -->\n<line marker-end="url(#p22-f4-ok-arrow)" stroke="#22c55e" stroke-width="2" x1="210" x2="210" y1="167" y2="181"></line>\n<!-- Box 3: Dropped & Secured -->\n<g transform="translate(16, 184)">\n<rect fill="#052e16" height="88" rx="6" stroke="#22c55e" stroke-width="1.5" width="388"></rect>\n<text fill="#ffffff" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="12" y="22">[CORRECTED PATH: PACKET DROPPED &amp; ISOLATED]</text>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="40">✓ Staging TCP SYN dropped by distributed VPC firewall</text>\n<text fill="#bbf7d0" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="12" y="58">✓ bl-order-api allowed via mutual TLS on port 5432</text>\n<text fill="#86efac" font-family="system-ui, -apple-system, sans-serif" font-size="10" font-weight="600" x="12" y="74">Invariant Preserved: ≤ 1 physical fulfillment per unique order ID</text>\n</g>\n</g>\n<!-- Bottom Invariant Defense Summary -->\n<g transform="translate(40, 442)">\n<rect fill="#111827" height="60" rx="8" stroke="#334155" stroke-width="1.2" width="880"></rect>\n<text fill="#38bdf8" font-family="system-ui, -apple-system, sans-serif" font-size="11" font-weight="700" x="20" y="22">SECURITY BOUNDARY &amp; FULFILLMENT INVARIANT VERIFICATION:</text>\n<text fill="#cbd5e1" font-family="system-ui, -apple-system, sans-serif" font-size="10" x="20" y="42">Strict network isolation guarantees that only verified API instances can commit order transactions. Deduplication tokens in the database verify zero phantom rows or duplicated physical fulfillments occurred during the exposure window.</text>\n</g>\n</svg>\n</div>\n<figcaption>\n<strong>Figure 22.4: Incident Flow · Resource Label vs. Network Tag Conflation in VPC Firewall Filtering.</strong>\n    Visualizes how misconfiguring Terraform with Resource Labels instead of Network Tags left a production database instance without targeted packet filtering, causing traffic to fall through to an open internal subnet rule, and how explicit network and secure tagging corrected the vulnerability.\n    <br/><strong>Supplied facts:</strong> A Terraform deployment populated instance labels with <code>tier = "order-db"</code> but omitted the instance <code>tags</code> block, allowing non-production hosts to connect to port 5432.\n    <br/><strong>Architectural inference:</strong> VPC firewalls evaluate Compute Engine Network Tags and Resource Manager Secure Tags; they completely ignore resource labels, which exist strictly for billing and metadata query planes.\n    <br/><strong>Expected post-fix behavior:</strong> Explicit network tags bind the instance to targeted firewall rules, staging traffic is dropped at the VPC boundary, and deduplication tokens ensure ≤ 1 physical fulfillment per unique order ID.\n  </figcaption>\n</figure>'

